import {client,ensureProfile,loadPublic,publicPhoto,postPet,postSighting,updatePrivacy,myNotifications,readNotification,sightingPhoto,reportContent,blockUser,resolvePet} from './backend.js';
import {isNative,nativePhoto,nativePosition} from './native.js';

(()=>{'use strict';
const byId=id=>document.getElementById(id),app=byId('app'),view=byId('appScreen'),drawer=byId('menuDrawer'),award=byId('awardDialog');
const pawLogo='<svg viewBox="0 0 64 64" fill="currentColor" aria-hidden="true"><ellipse cx="14" cy="25" rx="6.8" ry="9" transform="rotate(-28 14 25)"/><ellipse cx="27" cy="14" rx="6.8" ry="9" transform="rotate(-8 27 14)"/><ellipse cx="42" cy="16" rx="6.8" ry="9" transform="rotate(15 42 16)"/><ellipse cx="53" cy="29" rx="6.8" ry="9" transform="rotate(32 53 29)"/><path d="M32 29c-7 0-10 8-17 16-6 8 0 15 8 12 7-3 11-3 18 0 8 3 14-4 8-12-7-8-10-16-17-16Z"/></svg>';
const uiPaths={'menu': '<path d="M4 7h16M4 12h16M4 17h10"/>', 'close': '<path d="m6 6 12 12M6 18 18 6"/>', 'arrow': '<path d="M5 12h14m-6-6 6 6-6 6"/>', 'back': '<path d="M19 12H5m6-6-6 6 6 6"/>', 'home': '<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>', 'user': '<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>', 'award': '<circle cx="12" cy="8" r="5"/><path d="m8 12-2 9 6-3 6 3-2-9"/>', 'map': '<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Zm6-2v16m6-14v16"/>', 'search': '<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>', 'plus': '<path d="M12 5v14M5 12h14"/>', 'exit': '<path d="M9 4H4v16h5m5-12 4 4-4 4m-6-4h12"/>'};
function uiIcon(key){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(uiPaths[key]||uiPaths.search)+'</svg>'}
const heroEmblem='<svg viewBox="0 0 224 196" fill="none" aria-hidden="true"><circle cx="112" cy="94" r="81" stroke="currentColor" opacity=".12" stroke-dasharray="4 8"/><path d="M25 132c14 21 62 29 86 21 47-15 78-10 90-34" stroke="currentColor" opacity=".13" stroke-width="1.5"/><rect x="57" y="27" width="114" height="114" rx="36" fill="#f6d34e" transform="rotate(-10 114 84)"/><path d="M113 48c-26 0-44 18-44 42 0 32 44 61 44 61s44-29 44-61c0-24-18-42-44-42Z" fill="currentColor"/><g transform="translate(86 62) scale(.84)" fill="#f6d34e"><ellipse cx="14" cy="25" rx="6.8" ry="9" transform="rotate(-28 14 25)"/><ellipse cx="27" cy="14" rx="6.8" ry="9" transform="rotate(-8 27 14)"/><ellipse cx="42" cy="16" rx="6.8" ry="9" transform="rotate(15 42 16)"/><ellipse cx="53" cy="29" rx="6.8" ry="9" transform="rotate(32 53 29)"/><path d="M32 29c-7 0-10 8-17 16-6 8 0 15 8 12 7-3 11-3 18 0 8 3 14-4 8-12-7-8-10-16-17-16Z"/></g><circle cx="34" cy="64" r="5" fill="#f6d34e"/><circle cx="188" cy="141" r="7" fill="#f6d34e"/><path d="M180 45v12m-6-6h12M48 152v10m-5-5h10" stroke="currentColor" stroke-width="2" stroke-linecap="round" opacity=".7"/></svg>';
const cameraSvg='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 6h4l2-3h4l2 3h4a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2Z"/><circle cx="12" cy="13" r="4"/></svg>';
const safe=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stamp=(day,hour,minute)=>{const d=new Date();d.setDate(d.getDate()-day);d.setHours(hour,minute,0,0);return d};
let dogs=[];
const heroes=[];
const reports=[];
const session={screen:'home',user:null,pending:null,captured:null,match:true,detailId:'pamuk',matchDogId:'pamuk',awardDogId:null,scan:0,locationIndex:0,postDraft:null,postRedirect:false,geoMessage:'',loaded:false,publishing:false,ranked:[],matchUnavailable:false};
const mapOrigin=[40.431,29.156];let activeMap=null,activeTiles=null,selectionMarker=null,activePicker=null;const mapTileUrl='https://tile.openstreetmap.org/{z}/{x}/{y}.png';
// Seed sightings are examples, never device positions.

let toastTimer=null,photoTimer=null;
function tier(count){return count>=5?{medal:'🥇',title:'Altın Kurtarıcı'}:count>=3?{medal:'🥈',title:'Gümüş Kâşif'}:count>=1?{medal:'🥉',title:'Bronz Dost'}:{medal:'🐾',title:'Yeni Pati Dostu'}}
function publicLabel(person){return person?.public?person.label:'Gizli kahraman'}
function dateOnly(at){return new Intl.DateTimeFormat('tr-TR',{day:'2-digit',month:'2-digit'}).format(at)}
function timeOnly(at){return new Intl.DateTimeFormat('tr-TR',{hour:'2-digit',minute:'2-digit'}).format(at)}
function longDate(at){return new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'}).format(at)}
function relTime(at){const m=Math.round((Date.now()-at)/60000);if(m<1)return'az önce';if(m<60)return m+' dk önce';const h=Math.round(m/60);if(h<48)return h+' saat önce';return Math.round(h/24)+' gün önce'}function distM(a,b){const R=6371000,r=x=>x*Math.PI/180,dLat=r(b.lat-a.lat),dLng=r(b.lng-a.lng),q=Math.sin(dLat/2)**2+Math.cos(r(a.lat))*Math.cos(r(b.lat))*Math.sin(dLng/2)**2;return 2*R*Math.asin(Math.sqrt(q))}function distLabel(m){return m<1000?'~'+Math.round(m/10)*10+' m':'~'+(m/1000).toFixed(1).replace('.',',')+' km'}function routeWindow(route){const w=session.trackWindow||'all';if(w==='all')return route;const lim=Date.now()-(w==='24h'?864e5:6048e5);return [route[0],...route.slice(1).filter(p=>p.at>=lim)]}const speciesNames={dog:'Köpek',cat:'Kedi',other:'Diğer'};function speciesLine(d){const s=speciesNames[d.species||'dog'];return d.breed&&d.breed!=='Belirtilmedi'&&d.breed!==s?s+' · '+d.breed:s}function speciesFilter(action){const w=session.speciesFilter||'all';return '<div class="segmented" role="group" aria-label="Türe göre süz">'+[['all','Tümü'],['dog','Köpek'],['cat','Kedi']].map(([k,t])=>'<button type="button" data-action="'+action+'" data-species="'+k+'" aria-pressed="'+(w===k)+'">'+t+'</button>').join('')+'</div>'}function bySpecies(list){const w=session.speciesFilter||'all';return w==='all'?list:list.filter(d=>(d.species||'dog')===w)}function dogById(id){return dogs.find(d=>d.id===id)}
function notice(text){clearTimeout(toastTimer);byId('appToast').textContent=text;byId('appToast').hidden=false;toastTimer=setTimeout(()=>byId('appToast').hidden=true,4500)}
function renderHeader(){const home=session.screen==='home';byId('appHeader').innerHTML=(home?'<span class="brand-lockup"><span class="mini-paw" aria-hidden="true">'+pawLogo+'</span><span class="wordmark">PAWLO</span></span>':'<button type="button" class="back-button" data-action="home" aria-label="Ana sayfaya dön">'+uiIcon('back')+'<span class="wordmark">PAWLO</span></button>')+'<button type="button" class="icon-button" data-action="menu" aria-label="Menüyü aç" aria-controls="menuDrawer" aria-haspopup="dialog">'+uiIcon('menu')+'</button>'}
function navigate(screen){session.scan++;disposeMap();session.screen=screen;renderHeader();view.className='screen'+(screen==='home'?' home':'');renderScreen();window.scrollTo({top:0,behavior:'instant'});if(screen!=='home'){view.setAttribute('tabindex','-1');view.focus({preventScroll:true})}else view.removeAttribute('tabindex')}
function dogArt(side=false,kangal=false){const coat=kangal?'#bfb3a0':'#e6b774',ear=kangal?'#71656a':'#c48b49',muzzle=kangal?'#575060':'#fae1ad';return '<svg class="dog-art" viewBox="0 0 180 160" fill="none" aria-hidden="true"><circle cx="91" cy="96" r="57" fill="#fff" opacity=".3"/><ellipse cx="92" cy="148" rx="50" ry="5" fill="#34204f" opacity=".07"/>'+(side?'<path d="M41 91c-13-19-8-30-1-24 5 5 8 13 17 14" stroke="'+ear+'" stroke-width="10" stroke-linecap="round"/><path d="M49 85c11-8 42-4 57-4l14-25 20-3 9 17 15 5c4 6-3 14-17 14l-14 15-6 37h-12l-2-33-29 1-14 32H58l8-39-17-6Z" fill="'+coat+'"/><path d="m122 56 8 33c12 6 18-4 10-21l-5-14Z" fill="'+ear+'"/><circle cx="145" cy="70" r="2.5" fill="#30243a"/><path d="m158 74 9 2-3 6-6-1Z" fill="#30243a"/><path d="m113 99 14 4" stroke="#5b2ca8" stroke-width="6" stroke-linecap="round"/>':'<path d="M58 145c1-25 16-36 32-36 19 0 34 12 36 36" fill="'+coat+'"/><path d="M55 49c-23 1-25 41-18 57 5 11 21 7 28-10l5-32Zm70 0c23 1 25 41 18 57-5 11-21 7-28-10l-5-32Z" fill="'+ear+'"/><path d="M90 40c-29 0-41 19-38 46l5 21c8 23 59 23 66 0l5-21c3-27-9-46-38-46Z" fill="'+coat+'"/><ellipse cx="90" cy="100" rx="26" ry="22" fill="'+muzzle+'"/><ellipse cx="72" cy="79" rx="4" ry="5" fill="#30243a"/><ellipse cx="108" cy="79" rx="4" ry="5" fill="#30243a"/><path d="M81 95c0-6 18-6 18 0 0 5-7 10-9 10s-9-5-9-10Z" fill="#30243a"/><path d="M90 105v7m-10 1c4 5 16 5 20 0" stroke="'+(kangal?'#c6b8ad':'#946137')+'" stroke-width="2" stroke-linecap="round"/><path d="m70 129 40 0" stroke="#5b2ca8" stroke-width="8" stroke-linecap="round"/><circle cx="90" cy="133" r="6" fill="#f6d34e"/>')+'</svg>'}
function photoMarkup(dog,side=false){const photo=side?dog.side:dog.front;return '<div class="dog-photo '+(side?'side':'')+'" style="--photo-bg:'+(side?'#ebe3f5':'#f9edc8')+'"><span class="photo-tag">'+(side?'YANDAN':'ÖNDEN')+'</span>'+(photo?'<img src="'+safe(photo)+'" alt="'+safe(dog.label)+' '+(side?'yandan':'önden')+' fotoğrafı">':dogArt(side,dog.breed==='Kangal'))+'</div>'}
function dogCards(){const list=bySpecies(dogs.filter(d=>d.status==='lost'));if(!list.length)return '<p class="muted">Bu türde açık kayıp ilanı yok.</p>';return list.map(d=>'<button type="button" class="pet-card" data-action="detail" data-id="'+safe(d.id)+'" aria-label="'+safe(d.label)+' yol haritasını ve detayını aç"><div class="photo-duo">'+photoMarkup(d)+photoMarkup(d,true)+'</div><div class="pet-copy"><div class="pet-heading"><h3>'+safe(d.label)+'</h3>'+(d.reward?'<span class="reward">'+d.reward.toLocaleString('tr-TR')+' ₺ ödül</span>':'')+'</div><p class="pet-breed">'+safe(speciesLine(d))+'</p><div class="pet-meta"><span>⌖ '+safe(d.area)+'</span><span>◉ '+Math.max(0,d.route.length-1)+' görülme</span></div></div></button>').join('')}

function mapMarkup(dog,picker=false){return '<div class="map-frame"><div id="'+(picker?'postMap':'routeMap')+'" class="real-map" role="region" aria-label="'+(picker?'Konum seçme haritası':'Gerçek harita üzerinde görülme noktaları')+'" tabindex="0"></div>'+(picker?'<span class="map-crosshair" aria-hidden="true"></span>':'')+'<p id="mapLoadError" class="map-error" role="status" hidden></p></div>'+(picker?'':'<div class="map-legend"><span><i class="map-dot"></i>İlk konum</span><span><i class="map-dot violet"></i>Görülme</span><span>🐾 Son nokta</span></div>')}
function disposeMap(){if(activeMap)activeMap.remove();activeMap=null;activeTiles=null;selectionMarker=null;activePicker=null}
function validPoint(p){return p&&Number.isFinite(p.lat)&&Number.isFinite(p.lng)&&Math.abs(p.lat)<=90&&Math.abs(p.lng)<=180}
function pointLabel(p){return p.lat.toFixed(5)+', '+p.lng.toFixed(5)}
function getDevicePosition(ok,fail,options){if(isNative())nativePosition().then(ok).catch(fail);else navigator.geolocation.getCurrentPosition(ok,fail,options)}
function geoPoint(){return new Promise(resolve=>{if(!navigator.geolocation&&!isNative()){session.geoMessage='Bu cihaz konum hizmetini desteklemiyor. Konumu haritadan seçebilirsin.';resolve(null);return}getDevicePosition(pos=>{const p={lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy:Math.round(pos.coords.accuracy),source:'gps'};session.geoMessage='';resolve(validPoint(p)?p:null)},error=>{session.geoMessage=error.code===1?'Konum izni kapalı. Haritada gördüğün yeri seçebilirsin.':'Konum alınamadı. Haritadan bir nokta seçebilir veya tekrar deneyebilirsin.';resolve(null)},{enableHighAccuracy:true,maximumAge:0,timeout:8000})})}
function markerFor(p,first,last,num){return L.marker([p.lat,p.lng],{icon:L.divIcon({className:'paw-marker'+(first?' first':'')+(last?' last':''),html:'<span>'+(last?pawLogo:(num?num:''))+'</span>',iconSize:last?[38,38]:[28,28],iconAnchor:last?[19,19]:[14,14]}),title:p.place||'Seçilen konum',alt:p.place||'Konum işareti',keyboard:true})}
function mountMap(id,points=[],picker=null,overview=false){const el=byId(id);if(!el)return;disposeMap();activePicker=picker;const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;activeMap=L.map(el,{scrollWheelZoom:false,zoomControl:false,zoomAnimation:!reduced,fadeAnimation:!reduced,markerZoomAnimation:!reduced,worldCopyJump:true}).setView(mapOrigin,14);const map=activeMap;L.control.zoom({zoomInTitle:'Yakınlaştır',zoomOutTitle:'Uzaklaştır'}).addTo(map);activeTiles=L.tileLayer(mapTileUrl,{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> katkıcıları'}).addTo(map);activeTiles.on('tileerror',()=>{const warning=byId('mapLoadError');if(warning) {warning.hidden=false;warning.textContent='Harita görselleri yüklenemedi. İnternet bağlantını kontrol et. Noktalar ve konum seçimi kullanılabilir.'}});activeTiles.on('load',()=>{const warning=byId('mapLoadError');if(warning&&el.querySelectorAll('.leaflet-tile-loaded').length)warning.hidden=true});const valid=points.filter(validPoint);if(!picker&&valid.length>1&&!overview)L.polyline(valid.map(p=>[p.lat,p.lng]),{color:'#5b2ca8',weight:3,opacity:.75,dashArray:'6 8'}).addTo(map);valid.forEach((p,i)=>{const m=markerFor(p,i===0,i===valid.length-1||overview,!picker&&!overview?i+1:0).addTo(map);if(picker){selectionMarker=m;return}const content='<b>'+safe(p.dogLabel||p.place)+'</b><br>'+safe(p.place)+'<br>'+longDate(p.at)+(p.source==='gps'?'<br>Telefon konumu · ±'+p.accuracy+' m':p.source==='manual'?'<br>Haritadan seçildi':'<br>İlk kayıp konumu')+'<br><span class="map-coordinate">'+pointLabel(p)+'</span>'+(overview?'<br><button data-action="detail" data-id="'+safe(p.dogId)+'">İlanı aç</button>':'');m.bindPopup(content);if(!overview)m.bindTooltip(dateOnly(p.at)+'<br>'+timeOnly(p.at),{permanent:true,direction:'top',offset:[0,-19],className:'route-time'})});if(valid.length>1)map.fitBounds(L.latLngBounds(valid.map(p=>[p.lat,p.lng])),{padding:[42,65],maxZoom:16,animate:false});else if(valid.length)map.setView([valid[0].lat,valid[0].lng],16);if(picker){map.on('click',e=>selectMapPoint(e.latlng));el.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();selectMapPoint(map.getCenter())}})}requestAnimationFrame(()=>{if(activeMap===map)map.invalidateSize()})}
function selectMapPoint(p){const point={lat:Number(p.lat.toFixed(6)),lng:Number(L.Util.wrapNum(p.lng,[-180,180]).toFixed(6)),source:'manual'};if(!validPoint(point))return;if(activePicker==='post')session.postDraft.location=point;else if(activePicker==='sighting')session.pending.location=point;else return;if(selectionMarker)selectionMarker.setLatLng([point.lat,point.lng]);else selectionMarker=markerFor(point,false,true).addTo(activeMap);const status=byId('locationStatus');if(status)status.textContent='✓ Konum seçildi: '+pointLabel(point);const confirm=byId('confirmSighting');if(confirm)confirm.disabled=false}
function pickerTools(){return '<div class="map-tools"><button type="button" class="button secondary" data-action="locate">⌖ Konumumu kullan</button><button type="button" class="button secondary" data-action="select-center">Merkezi seç</button></div>'}
async function locateOnMap(button){const map=activeMap,picker=activePicker;button.disabled=true;const status=byId('locationStatus');if(status)status.textContent='Konumun alınıyor…';const p=await geoPoint();if(activeMap!==map||activePicker!==picker)return;button.disabled=false;if(!p){if(status)status.textContent=session.geoMessage;else notice(session.geoMessage);return}map.setView([p.lat,p.lng],16);if(picker){selectMapPoint(p);if(picker==='post')session.postDraft.location=p;else session.pending.location=p;if(status)status.textContent='✓ Telefon konumu: '+pointLabel(p)+' · ±'+p.accuracy+' m'}else {L.circleMarker([p.lat,p.lng],{radius:8,color:'#fff',fillColor:'#287bcc',fillOpacity:1}).addTo(map).bindPopup('Buradasın · ±'+p.accuracy+' m').openPopup()}}
function renderOverview(){view.innerHTML='<p class="eyebrow">Her iz bir umut</p><h1 class="page-title">Kayıplar haritada</h1><p class="lead">Son görülme noktalarına dokunarak ilanları aç.</p>'+mapMarkup(null).replace(/<div class="map-legend">.*?<\/div>/,'')+'<div class="map-tools"><button class="button secondary" data-action="locate">⌖ Konumuma git</button><button class="button secondary" data-action="lost">İlanları listele</button></div><p class="map-status">Aktif kayıp ilanlarının son görülme noktaları gösterilir.</p>';mountMap('routeMap',dogs.filter(d=>d.status==='lost').map(d=>({...d.route.at(-1),dogId:d.id,dogLabel:d.label})),null,true)}
function renderSightingLocation(){const p=session.pending;if(!p){navigate('home');return}view.innerHTML='<p class="eyebrow">Son bir iz</p><h1 class="page-title">Nerede gördün?</h1><p class="lead">'+safe(session.geoMessage||'Gördüğün yeri haritaya dokunarak seç.')+'</p>'+mapMarkup(null,true)+pickerTools()+'<p id="locationStatus" class="location-status" role="status">'+(p.location?'Seçili konum: '+pointLabel(p.location):'Henüz konum seçilmedi.')+'</p><button id="confirmSighting" class="button accent" data-action="confirm-sighting" '+(p.location?'':'disabled')+'>Bu konumu yayınla</button><p class="map-status">Yayınladığında bu konum görülme haritasında görünür. Fotoğrafı yalnızca sen ve ilanın sahibi açabilir.</p>';mountMap('postMap',p.location?[p.location]:[],'sighting')}

function renderDetail(){const d=dogById(session.detailId);if(!d)return;view.innerHTML='<p class="eyebrow">Kayıp dostumuz</p><h1 class="page-title">'+safe(d.label)+'</h1><p class="lead">'+safe(speciesLine(d))+(d.sample?' · Örnek ilan':'')+'</p><div class="photo-duo pet-detail-photos">'+photoMarkup(d)+photoMarkup(d,true)+'</div><dl class="detail-info"><div><dt>Son görüldüğü yer</dt><dd>'+safe(d.area)+'</dd></div><div><dt>Ödül</dt><dd>'+(d.reward?d.reward.toLocaleString('tr-TR')+' ₺':'Belirtilmedi')+'</dd></div></dl><h2 class="section-title">Yol haritası</h2>'+lastSeenCard(d)+trackFilter()+mapMarkup(d)+gmapsLink(d)+'<p class="muted" style="margin-top:10px">Gerçek harita · Kesikli çizgi görülme sırasını gösterir, yürüyüş rotası değildir.</p><h2 class="section-title">Adım adım izler</h2><ol class="timeline">'+d.route.slice().reverse().map((p,i)=>{const k=d.route.length-1-i,prev=d.route[k-1];return '<li class="'+(i===d.route.length-1?'first':'')+'"><b>'+(k+1)+'. '+longDate(p.at)+' · '+relTime(p.at)+'</b><p>'+safe(p.place)+(prev?' · önceki noktadan '+distLabel(distM(prev,p)):'')+'</p><small>'+(p.heroId?safe(publicLabel(heroes.find(h=>h.id===p.heroId))):'İlk kayıp konumu')+'</small></li>'}).join('')+'</ol>';view.innerHTML+='<div class="map-tools">'+(d.ownerId===session.user?.id&&d.status==='lost'?'<button class="button accent" data-action="resolve-pet">Yuvasına döndü</button>':d.ownerId!==session.user?.id?'<button class="button secondary" data-action="report-content">İlanı bildir</button><button class="button secondary" data-action="block-author">Kullanıcıyı gizle</button>':'')+'</div>';mountMap('routeMap',routeWindow(d.route))}


function gmapsLink(d){const last=d.route.at(-1);if(!last||!Number.isFinite(last.lat)||!Number.isFinite(last.lng))return '';const q=last.lat.toFixed(5)+','+last.lng.toFixed(5);return '<a class="button secondary gmaps-link" href="https://www.google.com/maps/search/?api=1&amp;query='+q+'" target="_blank" rel="noopener noreferrer">'+uiIcon('map')+'<span>Son noktayı Google Haritalar\'da aç</span></a>'}function lastSeenCard(d){const last=d.route.at(-1),n=d.route.length-1;return '<div class="track-summary" role="status"><span class="track-pulse" aria-hidden="true"></span><div><b>Son görülme: '+relTime(last.at)+'</b><small>'+(n?n+' görülme bildirimi · ':'Henüz görülme bildirimi yok · ')+(last.source==='gps'?'telefon konumu ±'+last.accuracy+' m':last.source==='manual'&&n?'haritadan seçildi':'ilk kayıp konumu')+'</small></div></div>'}function trackFilter(){const w=session.trackWindow||'all';return '<div class="segmented" role="group" aria-label="Zaman aralığı">'+[['all','Tümü'],['7d','Son 7 gün'],['24h','Son 24 saat']].map(([k,t])=>'<button type="button" data-action="track-window" data-window="'+k+'" aria-pressed="'+(w===k)+'">'+t+'</button>').join('')+'</div>'}function renderFound(){const sorted=heroes.slice().sort((a,b)=>b.count-a.count);view.innerHTML='<p class="eyebrow">İyi ki varsınız</p><h1 class="page-title">Pati kahramanları</h1><p class="lead">Her bildirim, eve dönüş yolunda yeni bir iz.</p><span class="demo-pill">PAWLO TOPLULUĞU</span><div class="card" style="margin-top:16px;padding-top:4px;padding-bottom:4px">'+sorted.map((h,i)=>{const t=tier(h.count);return '<div class="leader-row"><span class="leader-rank">'+(i+1)+'</span><span class="medal" aria-label="'+t.title+'">'+t.medal+'</span><div class="leader-body"><b>'+safe(publicLabel(h))+'</b><small>'+t.title+'</small></div><div class="leader-count">'+h.count+'<span>bildirim</span></div></div>'}).join('')+'</div><h2 class="section-title">Son bildirimler</h2><div class="card" style="padding-top:4px;padding-bottom:4px">'+reports.slice().sort((a,b)=>b.at-a.at).map(r=>{const h=heroes.find(p=>p.id===r.heroId),d=dogById(r.dogId);return '<div class="feed-row"><span class="feed-symbol">'+tier(h?.count||0).medal+'</span><div><p><b>'+safe(publicLabel(h))+'</b>, <b>'+safe(d?.label||'bir dostumuzu')+'</b> gördü.</p><small>'+safe(r.place)+' · '+longDate(r.at)+'</small></div></div>'}).join('')+'</div>'}



function readImage(file){return new Promise((resolve,reject)=>{if(!file.type.startsWith('image/'))return reject(Error('Lütfen bir görsel dosyası seç.'));if(file.size>12*1024*1024)return reject(Error('Fotoğraf en fazla 12 MB olabilir.'));const reader=new FileReader();reader.onerror=()=>reject(Error('Fotoğraf okunamadı.'));reader.onload=()=>{const image=new Image();image.onload=()=>resolve(reader.result);image.onerror=()=>reject(Error('Bu görsel açılamadı. JPEG veya PNG deneyebilirsin.'));image.src=reader.result};reader.readAsDataURL(file)})}
function readableError(error){const message=String(error?.message||error);if(/invalid login/i.test(message))return 'E-posta veya şifre hatalı.';if(/email not confirmed/i.test(message))return 'Lütfen önce e-postandaki doğrulama bağlantısını aç.';if(/rate limit|too many/i.test(message))return 'Çok fazla deneme yapıldı. Biraz sonra tekrar dene.';if(/email.*(invalid|sending)|smtp|email_address_not_authorized/i.test(message))return 'Doğrulama e-postası gönderilemedi. E-posta hizmeti ayarının tamamlanması gerekiyor.';if(/fetch|network/i.test(message))return 'Bağlantı kurulamadı. İnternetini kontrol edip tekrar dene.';return message}
async function refreshRecords(){const data=await loadPublic();heroes.splice(0,heroes.length,...data.heroes.map(h=>({id:h.user_id,label:h.display_name,public:true,count:h.report_count})));reports.splice(0,reports.length,...data.seen.map(r=>({id:r.id,heroId:r.reporter_id,dogId:r.pet_id,at:new Date(r.seen_at),place:'Konum: '+r.latitude.toFixed(5)+', '+r.longitude.toFixed(5)})));dogs=data.pets.map(p=>{const initial={lat:p.latitude,lng:p.longitude,at:new Date(p.last_seen_at),place:'İlk kayıp konumu',heroId:null,source:'manual'};const route=[initial,...data.seen.filter(r=>r.pet_id===p.id).map(r=>({lat:r.latitude,lng:r.longitude,at:new Date(r.seen_at),accuracy:r.accuracy,source:r.location_source,heroId:r.reporter_id,place:'Görülme: '+r.latitude.toFixed(5)+', '+r.longitude.toFixed(5)}))];return {id:p.id,label:p.pet_name,species:['dog','cat','other'].includes(p.species)?p.species:'dog',breed:p.breed,reward:Number(p.reward),front:publicPhoto(p.front_path),side:publicPhoto(p.side_path),area:'Konum: '+pointLabel(route.at(-1)),ownerId:p.owner_id,status:p.status,route,sample:false}});if(session.user)session.user.count=heroes.find(h=>h.id===session.user.id)?.count||0;session.loaded=true}
async function afterAuth(user,restoring){session.user=await ensureProfile(user);await refreshRecords();if(restoring){renderHeader();if(session.screen!=='home')navigate(session.screen);return}if(session.pending)await publishSighting();else if(session.postRedirect){session.postRedirect=false;navigate('post')}else navigate('account')}
function renderSignup(login=false){view.innerHTML='<p class="eyebrow">Bir patinin kahramanı ol</p><h1 class="page-title">'+(login?'Tekrar hoş geldin.':'Aramıza hoş geldin.')+'</h1><p class="lead">'+(session.pending?'Görülme bildirimin hazır. Giriş yaptıktan sonra seçtiğin konumu paylaşacağız.':'İlanlarını ve bildirimlerini hesabında takip et.')+'</p><form id="signupForm" class="card">'+(!login?'<div class="form-field"><label for="memberLabel">Adın</label><input id="memberLabel" name="memberLabel" autocomplete="given-name" maxlength="60" required placeholder="Adını yaz"></div>':'')+'<div class="form-field"><label for="memberEmail">E-posta adresin</label><input id="memberEmail" name="memberEmail" type="email" autocomplete="email" maxlength="160" required placeholder="ornek@eposta.com"></div><div class="form-field"><label for="memberPassword">Şifren</label><input id="memberPassword" name="memberPassword" type="password" minlength="10" maxlength="128" autocomplete="'+(login?'current-password':'new-password')+'" required placeholder="En az 10 karakter"></div>'+(!login?'<label class="check-row"><input type="checkbox" name="publicLabel" checked><span>Adım Bulunanlar bölümünde görünsün (rütbem ve madalyam da).</span></label><p class="muted">Kapalıysa adın “Gizli kahraman” olarak görünür.</p>':'')+'<p id="signupError" class="error" role="alert"></p><button type="submit" class="button accent">'+(login?(session.pending?'Giriş yap ve yayınla':'Giriş yap'):'Üye ol')+'</button><button type="button" class="button secondary" data-action="'+(login?'signup':'login')+'">'+(login?'Hesabım yok, üye ol':'Zaten üyeyim, giriş yap')+'</button><button type="button" class="button secondary" data-action="privacy">Gizlilik ve veriler</button></form>';byId('signupForm').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('[type=submit]');button.disabled=true;const form=new FormData(e.currentTarget),email=String(form.get('memberEmail')).trim(),password=String(form.get('memberPassword'));try{if(login){const {data,error}=await client.auth.signInWithPassword({email,password});if(error)throw error;await afterAuth(data.user)}else{const fullName=String(form.get('memberLabel')).trim();if(!fullName)throw Error('Lütfen adını yaz.');const {data,error}=await client.auth.signUp({email,password,options:{emailRedirectTo:'https://buldum-app.vercel.app/',data:{full_name:fullName,show_name:form.get('publicLabel')==='on'}}});if(error)throw error;if(data.session)await afterAuth(data.user);else{navigate('login');notice('Doğrulama e-postandaki bağlantıyı aç, ardından giriş yap.')}}}catch(error){if(byId('signupError'))byId('signupError').textContent=readableError(error);button.disabled=false}}}
function renderAccount(){if(!session.user){renderSignup(true);return}const u=session.user,t=tier(u.count),mine=dogs.filter(d=>d.ownerId===u.id);view.innerHTML='<p class="eyebrow">Senin pati hikâyen</p><h1 class="page-title">Hesabım</h1><div class="card account-hero"><div class="account-medal">'+t.medal+'</div><h2 class="account-tier">'+t.title+'</h2><p class="account-name">'+safe(u.label)+'</p><div class="account-total">'+u.count+'<span>görülme bildirimi</span></div></div><div class="card"><label class="check-row"><input type="checkbox" id="accountPrivacy" '+(u.public?'checked':'')+'><span>Adım Bulunanlar’da görünsün.</span></label><p class="muted">Kapalıysa adın yerine “Gizli kahraman” gösterilir.</p></div><p class="notice">🥉 1 bildirim: Bronz Dost<br>🥈 3 bildirim: Gümüş Kâşif<br>🥇 5 bildirim: Altın Kurtarıcı</p><h2 class="section-title">İlanlarım</h2>'+mine.map(d=>'<button class="button secondary" data-action="detail" data-id="'+safe(d.id)+'">'+safe(d.label)+(d.status==='reunited'?' · Yuvasına döndü':' · Aranıyor')+'</button>').join('')+(!mine.length?'<p class="muted">Henüz bir ilan vermedin.</p>':'')+'<h2 class="section-title">Hesap ve veriler</h2><button class="button secondary" data-action="privacy">Gizlilik ve veriler</button><button class="button secondary" data-action="delete-account">Hesabımı ve verilerimi sil</button>';byId('accountPrivacy').onchange=async e=>{const checkbox=e.target,old=u.public;checkbox.disabled=true;try{await updatePrivacy(u,checkbox.checked);u.public=checkbox.checked;await refreshRecords();notice('Görünürlük tercihin kaydedildi.')}catch(error){checkbox.checked=old;notice(readableError(error))}finally{checkbox.disabled=false}}}
function renderPost(){if(!session.user){session.postRedirect=true;navigate('signup');return}session.postDraft??={front:null,side:null,location:null};const draft=session.postDraft;view.innerHTML='<p class="eyebrow">Kayıp dostunu duyur</p><h1 class="page-title">Kayıp ilanı ver</h1><p class="lead">Fotoğraflarını ekle ve en son gördüğün yeri işaretle.</p><form id="postForm"><div class="card"><fieldset class="form-field species-pick"><legend>Türü</legend><div class="segmented">'+[['dog','Köpek'],['cat','Kedi'],['other','Diğer']].map(([k,t],i)=>'<label class="seg-option"><input type="radio" name="petSpecies" value="'+k+'"'+(i===0?' checked':'')+'><span>'+t+'</span></label>').join('')+'</div></fieldset><div class="form-field"><label for="dogLabel">Dostunun adı</label><input id="dogLabel" name="dogLabel" required maxlength="60" placeholder="Örn. Pamuk"></div><div class="form-field"><label for="dogBreed">Cinsi · biliyorsan</label><input id="dogBreed" name="dogBreed" maxlength="100" placeholder="Örn. Golden Retriever, Tekir"></div><div class="photo-duo"><label class="upload-field"><input id="postFront" type="file" accept="image/*" required><span class="preview-box" id="frontPreview">'+cameraSvg+'</span><span>Önden fotoğraf</span><small>Fotoğraf seç</small></label><label class="upload-field"><input id="postSide" type="file" accept="image/*" required><span class="preview-box" id="sidePreview">'+cameraSvg+'</span><span>Yandan fotoğraf</span><small>Fotoğraf seç</small></label></div></div><h2 class="section-title">Son görüldüğü konum</h2><p class="muted" style="margin-bottom:12px">Haritaya dokunarak bir nokta seç.</p>'+mapMarkup(null,true)+pickerTools()+'<p id="locationStatus" class="location-status" role="status">'+(draft.location?'Seçili konum: '+pointLabel(draft.location):'Henüz konum seçilmedi.')+'</p><div class="card" style="margin-top:22px"><label for="dogReward">Ödül miktarı (₺) · isteğe bağlı</label><input id="dogReward" name="dogReward" type="number" inputmode="decimal" min="0" max="10000000" step="1" placeholder="Örn. 5000"></div><p class="notice">İlanı yayınladığında iki fotoğraf ve seçtiğin konum herkes tarafından görülebilir. Ev adresi veya kişisel bilgi içeren fotoğraflar kullanma.</p><p id="postError" class="error" role="alert"></p><button type="submit" class="button accent">İlanı yayınla</button></form>';mountMap('postMap',draft.location?[draft.location]:[],'post');['front','side'].forEach(which=>{const input=byId(which==='front'?'postFront':'postSide');input.onchange=async()=>{try{const file=input.files[0];if(!file)return;draft[which]=await readImage(file);byId(which==='front'?'frontPreview':'sidePreview').innerHTML='<img src="'+safe(draft[which])+'" alt="'+(which==='front'?'Önden':'Yandan')+' fotoğraf önizlemesi">'}catch(error){draft[which]=null;input.value='';byId('postError').textContent=readableError(error)}}});byId('postForm').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('[type=submit]'),form=new FormData(e.currentTarget);try{if(!draft.front||!draft.side)throw Error('İki fotoğrafı da seç ve yüklenmesini bekle.');if(!validPoint(draft.location))throw Error('Lütfen haritadan konumu seç.');button.disabled=true;button.textContent='Fotoğraflar yükleniyor…';const pet=await postPet(draft,session.user,String(form.get('dogLabel')).trim(),String(form.get('dogBreed')).trim()||'Belirtilmedi',Number(form.get('dogReward'))||0,String(form.get('petSpecies')||'dog'));session.postDraft=null;try{await refreshRecords()}catch{}if(!dogById(pet.id)){dogs.unshift({id:pet.id,label:pet.pet_name,species:pet.species||String(form.get('petSpecies')||'dog'),breed:pet.breed,reward:Number(pet.reward),front:publicPhoto(pet.front_path),side:publicPhoto(pet.side_path),ownerId:pet.owner_id,status:pet.status,area:'Konum: '+pet.latitude.toFixed(5)+', '+pet.longitude.toFixed(5),route:[{lat:pet.latitude,lng:pet.longitude,at:new Date(pet.last_seen_at),place:'İlk kayıp konumu',source:'manual',heroId:null}]})}session.detailId=pet.id;navigate('detail');notice('İlanın yayınlandı.')}catch(error){if(byId('postError'))byId('postError').textContent=readableError(error);button.disabled=false;button.textContent='İlanı yayınla'}}}
function openMenu(){const u=session.user,t=tier(u?.count||0),dark=app.dataset.theme==='dark';const entries=[[u?'account':'signup','user',u?'Hesabım':'Üye ol'],...(!u?[['login','user','Giriş yap']]:[]),['home','home','Ana sayfa'],['found','award','Bulunanlar'],['map','map','Harita'],['lost','search','Kayıplar'],['post','plus','Kayıp ilanı ver'],...(u?[['notifications','award','Bildirimler']]:[]),['refresh','arrow','Verileri yenile'],['privacy','user','Gizlilik ve veriler'],...(u?[['logout','exit','Çıkış yap']]:[])];byId('menuContent').innerHTML='<div class="drawer-top"><span class="wordmark">PAWLO</span><button type="button" class="icon-button" data-action="close-menu" aria-label="Menüyü kapat">'+uiIcon('close')+'</button></div><div class="drawer-user"><span class="user-avatar">'+(u?t.medal:pawLogo)+'</span><div><b>'+safe(u?u.label:'Misafir')+'</b><p>'+(u?t.title:'Bir patinin kahramanı olabilirsin.')+'</p></div></div><nav class="drawer-nav" aria-label="Ana menü">'+entries.map(([action,icon,label])=>'<button data-action="'+action+'" '+(session.screen===action?'aria-current="page"':'')+'><span class="nav-icon">'+uiIcon(icon)+'</span>'+label+'</button>').join('')+'</nav><div class="drawer-settings"><div class="setting-row"><span>Koyu tema</span><button type="button" class="switch" role="switch" aria-label="Koyu tema" aria-checked="'+dark+'" data-action="theme"></button></div><p class="drawer-note">PAWLO Beta · Fotoğraf benzerliği kesin kimlik tespiti değildir. Bir eşleşmeyi paylaşmadan önce hayvanı dikkatle karşılaştır.</p></div>';if(!drawer.open)drawer.showModal()}
async function beginCapture(){if(!session.loaded){notice('İlanlar yükleniyor. Biraz sonra tekrar dene.');return}session.pending=null;if(isNative()){try{await processPhoto(await nativePhoto())}catch(error){notice('Fotoğraf çekimi tamamlanmadı.')}return}byId('cameraFile').value='';byId('cameraFile').click()}
async function processPhoto(file){try{session.captured=await readImage(file);navigate('scan');const token=session.scan;session.captureAt=new Date();await refreshRecords();if(token!==session.scan)return;const candidates=dogs.filter(d=>d.status==='lost'&&d.ownerId!==session.user?.id);if(!candidates.length){navigate('noMatch');return}const status=byId('scanProgress');try{if(status)status.textContent='Fotoğraf karşılaştırması hazırlanıyor… İlk kullanımda biraz sürebilir.';const {rankPhotos}=await import('./similarity.js');session.ranked=await rankPhotos(session.captured,candidates,(done,total)=>{if(token===session.scan&&byId('scanProgress'))byId('scanProgress').textContent=done+' / '+total+' ilan karşılaştırıldı.'});session.matchUnavailable=false}catch(error){session.ranked=candidates.slice(0,10).map(dog=>({dog,similarity:null}));session.matchUnavailable=true}if(token!==session.scan)return;navigate('candidates')}catch(error){notice(readableError(error));navigate('home')}}
function renderCandidates(){view.innerHTML='<p class="eyebrow">Birlikte doğrulayalım</p><h1 class="page-title">'+(session.matchUnavailable?'Kayıp ilanlarına bak':'Benzer ilanlar')+'</h1><p class="lead">'+(session.matchUnavailable?'Fotoğraf karşılaştırması şu an yüklenemedi. Aşağıdaki ilanlar benzerlik analizi yapılmadan gösteriliyor.':'Fotoğrafın genel görsel özelliklerine göre sıralandı. Bu sonuç bir kimlik doğrulaması veya eşleşme olasılığı değildir.')+'</p>'+speciesFilter('species-filter')+(bySpecies(session.ranked.map(r=>r.dog)).length?'':'<p class="muted">Bu türde benzer ilan yok. “Tümü”ne dokunarak hepsine bakabilirsin.</p>')+session.ranked.filter(r=>bySpecies([r.dog]).length).map(({dog:d})=>'<div class="card"><div class="photo-duo">'+photoMarkup(d)+photoMarkup(d,true)+'</div><h2 class="section-title">'+safe(d.label)+'</h2><p class="lead">'+safe(speciesLine(d))+'</p><button class="button accent" data-action="choose-match" data-id="'+safe(d.id)+'">Bu dostu gördüm</button></div>').join('')+'<button class="button secondary" data-action="home">Hiçbiri değil, ana sayfaya dön</button>'}
async function chooseMatch(id){const dog=dogById(id);if(!dog||!session.captured)return;session.pending={id:crypto.randomUUID(),dogId:id,photo:session.captured,location:null,at:session.captureAt||new Date()};navigate('findingLocation');const token=session.scan,point=await geoPoint();if(token!==session.scan)return;session.pending.location=point;if(session.user)await publishSighting();else navigate('signup')}
async function publishSighting(){const pending=session.pending,u=session.user;if(!pending||!u||session.publishing)return;if(!validPoint(pending.location)){navigate('sightingLocation');return}session.publishing=true;navigate('publishing');try{await postSighting(pending,u);session.awardDogId=pending.dogId;session.pending=null;session.captured=null;try{await refreshRecords()}catch{notice('Bildirim kaydedildi. Harita bağlantı gelince güncellenecek.')}navigate('published');const t=tier(u.count),dog=dogById(session.awardDogId);award.innerHTML='<button type="button" class="award-close" data-action="close-award" aria-label="Madalyayı kapat">×</button><span class="award-kicker">BİR PATİYE UMUT OLDUN</span><div class="award-medal">'+t.medal+'</div><h2 id="awardTitle">'+t.title+'</h2><p>'+safe(dog?.label)+' için görülme bildirimin kaydedildi.<br>Toplam <b>'+u.count+' bildirimin</b> var.</p><button class="button accent" data-action="award-route">Yol haritasını gör</button>';award.showModal()}catch(error){navigate('sightingLocation');notice('Bildirim kaydedilemedi: '+readableError(error))}finally{session.publishing=false}}
async function renderNotifications(){if(!session.user){navigate('login');return}view.innerHTML='<p class="eyebrow">Yeni izler</p><h1 class="page-title">Bildirimler</h1><p role="status" class="lead">Yükleniyor…</p>';try{const list=await myNotifications();if(session.screen!=='notifications')return;view.innerHTML='<p class="eyebrow">Yeni izler</p><h1 class="page-title">Bildirimler</h1>'+(!list.length?'<div class="card"><p class="lead">İlanlarına yeni bir görülme bildirimi geldiğinde burada görünecek.</p></div>':list.map(n=>{const r=n.sightings,d=dogById(r?.pet_id);return '<div class="card"><p class="eyebrow">'+(n.is_read?'Görüldü':'Yeni görülme')+'</p><h2>'+safe(d?.label||'İlanın')+'</h2><p class="lead">'+longDate(new Date(n.created_at))+'</p><button class="button" data-action="notification-detail" data-id="'+safe(n.id)+'" data-pet="'+safe(r?.pet_id)+'" data-photo="'+safe(r?.photo_path||'')+'">Fotoğraf ve konumu gör</button></div>'}).join(''))}catch(error){notice(readableError(error))}}
function renderPrivacy(){view.innerHTML='<p class="eyebrow">Kontrol sende</p><h1 class="page-title">Gizlilik ve veriler</h1><div class="card"><h2 class="section-title" style="margin-top:0">Neler kaydedilir?</h2><p class="lead">Hesap adı ve e-posta adresi; yayınladığın hayvan fotoğrafları, ilan bilgileri ve seçtiğin konumlar kaydedilir. Şifren kimlik doğrulama hizmeti tarafından korunur.</p><h2 class="section-title">Kimler görebilir?</h2><p class="lead">Kayıp ilanlarının fotoğrafları ve konumları herkese açıktır. Görülme noktaları haritada görünür. Gördüğün hayvanın bildirim fotoğrafını yalnızca sen ve ilgili ilanın sahibi açabilir. Adını gizlersen toplulukta “Gizli kahraman” görünürsün; e-posta adresin toplulukta paylaşılmaz.</p><h2 class="section-title">Fotoğraf karşılaştırması</h2><p class="lead">Fotoğrafın cihazında işlenir; karşılaştırma için bir yapay zekâ sağlayıcısına gönderilmez. Genel görsel benzerlik sıralaması kesin hayvan kimliği tespiti değildir.</p><h2 class="section-title">Harita ve barındırma</h2><p class="lead">Veriler Supabase’in Frankfurt bölgesindeki PAWLO projesinde tutulur. Web uygulaması Vercel’de barındırılır. Harita görselleri OpenStreetMap’ten yüklenir; görüntülenen alan ve bağlantı bilgileri bu servise iletilir. Konumuna yalnızca izin verdiğinde erişilir.</p><h2 class="section-title">Silme ve içerik bildirimi</h2><p class="lead">Hesabım bölümünden hesabını, ilanlarını, görülme bildirimlerini ve fotoğraflarını silebilirsin. Uygunsuz ilanları ilan detayından bildirebilir veya kullanıcıyı gizleyebilirsin.</p><h2 class="section-title">Diğer servisler</h2><p class="lead">Fotoğraf karşılaştırma modeli ilk kullanımda Google’ın sunucusundan indirilir; fotoğrafın gönderilmez. “Google Haritalar’da aç” butonuna basarsan seçtiğin konum Google Haritalar’da açılır.</p></div><a class="button secondary" href="/gizlilik.html">Gizlilik Politikası ve KVKK Aydınlatma Metni</a><a class="button secondary" href="/hesap-silme.html">Web’den hesap silme sayfası</a>'}
function renderDeleteAccount(){if(!session.user){navigate('login');return}view.innerHTML='<p class="eyebrow">Hesap yönetimi</p><h1 class="page-title">Hesabını sil</h1><div class="card"><p class="lead">Hesabın, ilanların, fotoğrafların ve görülme bildirimlerin kalıcı olarak silinir. Bu işlem geri alınamaz.</p><form id="deleteAccountForm"><div class="form-field"><label for="deletePassword">Şifrenle doğrula</label><input id="deletePassword" type="password" autocomplete="current-password" required minlength="10"></div><div class="form-field"><label for="deletePhrase">Onaylamak için SİL yaz</label><input id="deletePhrase" required autocomplete="off"></div><p id="deleteError" class="error" role="alert"></p><button class="button" type="submit">Hesabımı kalıcı olarak sil</button></form></div>';byId('deleteAccountForm').onsubmit=async e=>{e.preventDefault();if(byId('deletePhrase').value!=='SİL'){byId('deleteError').textContent='Lütfen SİL yazarak onayla.';return}const button=e.currentTarget.querySelector('button');button.disabled=true;try{const {error}=await client.functions.invoke('delete-account',{body:{password:byId('deletePassword').value,confirmation:'SİL'}});if(error)throw error;await client.auth.signOut();session.user=null;session.pending=null;await refreshRecords();navigate('home');notice('Hesabın ve verilerin silindi.')}catch(error){byId('deleteError').textContent='Hesap silinemedi. Şifreni ve bağlantını kontrol edip tekrar dene.';button.disabled=false}}}
function renderReport(){if(!session.user){navigate('login');notice('İçerik bildirmek için giriş yap.');return}view.innerHTML='<p class="eyebrow">Topluluğu birlikte koruyalım</p><h1 class="page-title">İlanı bildir</h1><form class="card" id="reportForm"><div class="form-field"><label for="reportReason">Bildirim nedeni</label><input id="reportReason" required minlength="3" maxlength="1000" placeholder="Yanlış bilgi, uygunsuz içerik…"></div><p id="reportError" class="error" role="alert"></p><button class="button" type="submit">Bildirimi gönder</button></form>';byId('reportForm').onsubmit=async e=>{e.preventDefault();try{await reportContent(session.user,session.detailId,byId('reportReason').value.trim());navigate('detail');notice('İçerik bildirimin kaydedildi.')}catch(error){byId('reportError').textContent=readableError(error)}}}

function renderScreen(){switch(session.screen){case'home':view.innerHTML='<section class="home-intro"><h1 class="home-heading">Kayıp bir dost mu gördün?</h1><p class="home-sub">Fotoğrafını çek, kayıp ilanlarıyla yan yana koyup birlikte bakalım.</p></section><button type="button" class="found-cta" data-action="capture" aria-label="Buldum: gördüğün hayvanın fotoğrafını çek veya galeriden seç"><span class="found-cta-mark" aria-hidden="true">'+pawLogo+'</span><span class="found-cta-icon" aria-hidden="true">'+cameraSvg+'</span><span class="found-cta-text"><b>BULDUM</b><small>Fotoğraf çek veya galeriden seç</small></span><span class="cta-arrow" aria-hidden="true">'+uiIcon('arrow')+'</span></button><div class="home-actions"><button type="button" class="home-tile" data-action="post" aria-label="Dostumu kaybettim: kayıp ilanı ver"><span class="home-tile-icon" aria-hidden="true">'+uiIcon('plus')+'</span><span class="home-tile-text"><b>Dostumu kaybettim</b><small>Kayıp ilanı ver</small></span></button><button type="button" class="home-tile" data-action="lost" aria-label="Bir yerde gördüm: ilanı seç, konum bildir"><span class="home-tile-icon" aria-hidden="true">'+uiIcon('search')+'</span><span class="home-tile-text"><b>Bir yerde gördüm</b><small>İlanı seç, konum bildir</small></span></button></div><button type="button" class="home-maplink" data-action="map"><span class="home-tile-icon" aria-hidden="true">'+uiIcon('map')+'</span><span>Kayıp ilanları haritada gör</span><span class="home-maplink-arrow" aria-hidden="true">'+uiIcon('arrow')+'</span></button><section class="home-how" aria-labelledby="homeHowTitle"><h2 id="homeHowTitle">Buldum nasıl işler?</h2><ol><li><b>Fotoğraf çek</b><span>Gördüğün dostun net bir fotoğrafı yeterli.</span></li><li><b>Benzer ilanlara bak</b><span>Uygulama ilanları görünüşe göre sıralar; kesin kimlik tespiti yapmaz.</span></li><li><b>Doğru dostu seç</b><span>Konumu paylaş, ilan sahibine bildirim gitsin.</span></li></ol></section><p class="home-note">Kayıp patimi bul! Kahramanım ol! İlanlara bakmak için üyelik gerekmez.</p>';break;case'scan':view.innerHTML='<div class="center-screen" role="status" aria-live="polite"><div class="scan-ring">'+(session.captured?'<img src="'+safe(session.captured)+'" alt="Çektiğin fotoğraf">':'<span class="scan-paw">🐾</span>')+'</div><h2>Fotoğrafın<br>karşılaştırılıyor…</h2><p>Minik izler, büyük umutlar.<br>Kayıp dostlarımızın fotoğraflarına bakıyoruz.</p><p id="scanProgress" class="muted" role="status">İlanlar hazırlanıyor…</p></div>';break;case'noMatch':view.innerHTML='<div class="center-screen"><div class="empty-icon">🔎</div><h1 class="page-title">Eşleşme bulunamadı</h1><p>Karşılaştırılabilecek aktif bir kayıp ilanı yok. Daha sonra yeniden deneyebilirsin.</p><button type="button" class="button" data-action="home">Ana sayfaya dön</button></div>';break;case'published':{const d=dogById(session.awardDogId);view.innerHTML='<div class="center-screen"><div class="empty-icon">✓</div><h1 class="page-title">Yeni bir iz bıraktın!</h1><p>'+safe(d?.label||'Dostumuz')+' için görülme bildirimin kaydedildi ve ilan sahibine uygulama içi bildirim oluşturuldu. İyi ki varsın.</p><button type="button" class="button" data-action="award-route">Yol haritasını gör</button><button type="button" class="button secondary" data-action="home">Ana sayfaya dön</button></div>';break}case'signup':renderSignup();break;case'account':renderAccount();break;case'login':renderSignup(true);break;case'candidates':renderCandidates();break;case'notifications':renderNotifications();break;case'privacy':renderPrivacy();break;case'deleteAccount':renderDeleteAccount();break;case'report':renderReport();break;case'findingLocation':view.innerHTML='<div class="center-screen" role="status"><div class="scan-ring">'+pawLogo+'</div><h2>Konumun alınıyor…</h2><p>Gördüğün yeri belirliyoruz.</p></div>';break;case'publishing':view.innerHTML='<div class="center-screen" role="status"><div class="scan-ring">'+pawLogo+'</div><h2>Bildirim kaydediliyor…</h2><p>Fotoğraf ve konumun ilanın sahibine ulaştırılıyor.</p></div>';break;case'map':renderOverview();break;case'sightingLocation':renderSightingLocation();break;case'lost':view.innerHTML='<p class="eyebrow">Yuvası onu bekliyor</p><h1 class="page-title">Kayıp patiler</h1><p class="lead">Bir fotoğrafı tanımak, bir ailenin umudunu büyütebilir.</p>'+speciesFilter('species-filter')+dogCards();break;case'detail':renderDetail();break;case'found':renderFound();break;case'post':renderPost();break}}


byId('cameraFile').onchange=e=>{const file=e.target.files?.[0];if(file)processPhoto(file)};

document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(action==='menu'){openMenu();return}if(action==='close-menu'){drawer.close();return}if(action==='theme'){app.dataset.theme=app.dataset.theme==='dark'?'light':'dark';document.querySelector('meta[name=theme-color]').content=app.dataset.theme==='dark'?'#191322':'#5b2ca8';openMenu();return}if(drawer.open)drawer.close();if(action==='close-award'){award.close();return}if(action==='award-route'){if(award.open)award.close();session.detailId=session.awardDogId;navigate('detail');return}if(action==='locate'){locateOnMap(b);return}if(action==='select-center'){if(activeMap)selectMapPoint(activeMap.getCenter());return}if(action==='confirm-sighting'){publishSighting();return}if(action==='refresh'){try{await refreshRecords();if(['lost','found','map','detail'].includes(session.screen))navigate(session.screen);notice('İlanlar güncellendi.')}catch(error){notice(readableError(error))}return}if(action==='choose-match'){await chooseMatch(b.dataset.id);return}if(action==='delete-account'){navigate('deleteAccount');return}if(action==='report-content'){navigate('report');return}if(action==='block-author'){if(!session.user){navigate('login');return}const d=dogById(session.detailId);if(d&&confirm('Bu kullanıcının ilanlarını gizlemek istiyor musun?')){try{await blockUser(session.user,d.ownerId);await refreshRecords();navigate('lost');notice('Kullanıcı gizlendi.')}catch(error){notice(readableError(error))}}return}if(action==='resolve-pet'){if(confirm('Bu dostumuzun yuvasına döndüğünü onaylıyor musun?')){try{await resolvePet(session.detailId);await refreshRecords();navigate('account');notice('Ne güzel haber! İlanın arama listesinden kaldırıldı.')}catch(error){notice(readableError(error))}}return}if(action==='notification-detail'){try{await readNotification(b.dataset.id);session.detailId=b.dataset.pet;navigate('detail');if(b.dataset.photo){const url=await sightingPhoto(b.dataset.photo),container=document.createElement('div');container.className='card';const img=document.createElement('img');img.src=url;img.alt='Görülme bildirimi fotoğrafı';img.style.cssText='width:100%;border-radius:16px';container.append(img);view.prepend(container)}}catch(error){notice(readableError(error))}return}if(action==='species-filter'){session.speciesFilter=b.dataset.species;navigate(session.screen);return}if(action==='track-window'){session.trackWindow=b.dataset.window;navigate('detail');return}if(action==='capture'){beginCapture();return}if(action==='detail'){session.detailId=b.dataset.id;navigate('detail');return}if(action==='logout'){await client.auth.signOut();session.user=null;session.pending=null;session.postDraft=null;session.postRedirect=false;navigate('home');await refreshRecords();notice('Çıkış yaptın.');return}if(action==='post'&&!session.user){session.postRedirect=true;navigate('signup');return}if(['home','signup','login','account','found','lost','post','map','notifications','privacy'].includes(action))navigate(action)});
drawer.addEventListener('click',e=>{if(e.target===drawer){const r=drawer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right)drawer.close()}});
if(window.matchMedia?.('(prefers-color-scheme: dark)').matches)app.dataset.theme='dark';
navigate('home');
refreshRecords().catch(error=>notice('İlanlar yüklenemedi: '+readableError(error)));
client.auth.getSession().then(({data})=>{if(data.session)afterAuth(data.session.user,true).catch(error=>notice(readableError(error)))});
})();
